/// V200-EVAL-RHC-DAYS
fn p_v200_eval_rhc_days(state: &mut ProgramState) {
    if state.rhc_logic_values.prior_svc_days >= 60 {
        state.rhc_logic_values.lr_bill_units1 = state.bill_315_data.bill_group1.bill_units1 as u32;
        p_v200_apply_low_rhc_rate(state);
        p_v200_apply_low_rhc_rate_exit(state);
        p_v200_eval_rhc_days_exit(state); return;
    }
    if state.rhc_logic_values.prior_svc_days < 60 {
        state.date_calculation_fields.high_rate_days_left = (60 as i64 - state.rhc_logic_values.prior_svc_days as i64) as i32;
        if state.bill_315_data.bill_group1.bill_units1 <= state.date_calculation_fields.high_rate_days_left as u32 {
            state.rhc_logic_values.hr_bill_units1 = state.bill_315_data.bill_group1.bill_units1 as u32;
            p_v200_apply_high_rhc_rate(state);
            p_v200_apply_high_rhc_rate_exit(state);
            p_v200_eval_rhc_days_exit(state); return;
        }
    }
}

