    state.rhc_logic_values.sia_pay_amt_total = Decimal::from(i64::from(state.bill_315_data.bill_sia_add_on_pymts.bill_eol_add_on_day1_pay + state.bill_315_data.bill_sia_add_on_pymts.bill_eol_add_on_day2_pay + state.bill_315_data.bill_sia_add_on_pymts.bill_eol_add_on_day3_pay + state.bill_315_data.bill_sia_add_on_pymts.bill_eol_add_on_day4_pay + state.bill_315_data.bill_sia_add_on_pymts.bill_eol_add_on_day5_pay + state.bill_315_data.bill_sia_add_on_pymts.bill_eol_add_on_day6_pay + state.bill_315_data.bill_sia_add_on_pymts.bill_eol_add_on_day7_pay));
