/// V210-CALC-PRIOR-SVC-DAYS
fn p_v210_calc_prior_svc_days(state: &mut ProgramState) {
    state.date_calculation_fields.date_1_adm = format!("{}", state.bill_315_data.bill_admission_date).trim().parse::<u32>().unwrap_or(0);
    state.date_calculation_fields.date_1_adm_integer = (state.date_calculation_fields.date_1_adm) as u32;
    state.date_calculation_fields.date_2_dos_integer = (state.date_calculation_fields.date_2_dos) as u32;
    state.date_calculation_fields.days_between_dates = (state.date_calculation_fields.date_2_dos_integer - state.date_calculation_fields.date_1_adm_integer) as i32;
    if state.bill_315_data.bill_sia_add_on_units.bill_na_add_on_day1_units > 0 {
        state.rhc_logic_values.prior_benefit_days = (state.bill_315_data.bill_sia_add_on_units.bill_na_add_on_day1_units) as u32;
    } else {
        state.rhc_logic_values.prior_benefit_days = 0;
    }
    state.rhc_logic_values.prior_svc_days = (state.date_calculation_fields.days_between_dates as i64 + state.rhc_logic_values.prior_benefit_days as i64) as u32;
}

